"""Sub-pipelines: the call op, invoking a top-level def with bound params."""

import re

from etl.errors import schema_error
from etl.fields import Field, Label
from etl.steps import Op, register

NAME_RE = re.compile(r'[A-Za-z_][A-Za-z0-9_]*\Z')

class DefName(Label):
    """Identifier naming a def."""

    def normalize(self, value, path):
        value = super().normalize(value, path)
        if not NAME_RE.match(value):
            raise schema_error("'%s' must match ^[A-Za-z_][A-Za-z0-9_]*$" % self.key, path)
        return value

def check_param(value, path):
    if isinstance(value, dict):
        raise schema_error('params values must not be objects', path)
    if isinstance(value, list):
        for i, v in enumerate(value):
            check_param(v, '%s[%d]' % (path, i))

class Params(Field):
    """Object of JSON scalar/array values (no nested objects)."""

    def normalize(self, value, path):
        if not isinstance(value, dict):
            raise schema_error("'%s' must be an object" % self.key, path)
        for k, v in value.items():
            check_param(v, '%s.%s' % (path, k))
        return dict(value)

@register
class Call(Op):
    name = 'call'
    fields = (DefName('name'), Params('params', required=False, default={}))

    def run(self, step, rows, ctx):
        saved = ctx.params
        ctx.params = step['params']
        try:
            return ctx.run(ctx.defs[step['name']], rows)
        finally:
            ctx.params = saved
